/* ================= teacher, school admin & moderation (laptop) ================= */
const TNAV = [['T01', 'home', 'Home'], ['T02', 'users', 'Class & roster'], ['T03', 'assign', 'Assign work'], ['T04', 'chart', 'Progress'], ['T05', 'badge', 'Badges'], ['T06', 'tablet', 'Classroom mode']];
const SNAV = [['S01', 'school', 'School & licence'], ['S02', 'chart', 'Reports & library'], ['M01', 'shield', 'Moderation']];
function laptop(body, o = {}) {
  const nav = o.nav || TNAV; const cur = o.cur || U.screen; const tab = D('teacher') === 'tablet' && U.app === 'teacher';
  return `<div class="a${tab ? ' tt' : ''}" style="display:flex;flex-direction:column">${tab ? '' : `<div class="urlbar"><i></i><i></i><i></i><span>${esc(o.url || 'app.trailbuddies.africa/teach')}</span></div>`}
    <div style="flex:1;display:flex;min-height:0">${o.nonav ? '' : `<nav class="nav${o.dark ? ' dark' : ''}"><div class="brand">${buddySVG('juma', { size: 34, still: true })}${tab ? '' : 'Trailbuddies'}</div>${nav.map(([to, ic, n]) => `<button type="button" data-to="${to}" ${cur === to ? 'aria-current="page"' : ''}>${I(ic)}${n}</button>`).join('')}
      <div style="flex:1"></div>${tab ? `<span class="av" style="background:var(--berry);align-self:center" title="Ms Priya Nair">P</span>` : `<div class="card" style="padding:10px;gap:2px"><b style="font-size:14px">${o.who || 'Ms Priya Nair'}</b><span class="mut">${o.role || 'Teacher · Hillside Primary'}</span></div>`}</nav>`}
      <main class="main">${body}</main></div></div>`;
}
const head = (t, sub, right = '') => `<div class="row" style="align-items:flex-end"><div><h1 style="font-size:32px">${t}</h1>${sub ? `<div class="mut" style="font-size:15px;margin-top:4px">${sub}</div>` : ''}</div><div style="display:flex;gap:10px">${right}</div></div>`;
const stat = (n, l, tone = '') => `<div class="card" style="flex:1;${tone ? `background:var(--${tone}-soft);border-color:var(--${tone})` : ''}"><span class="big tnum">${n}</span><span class="mut">${l}</span></div>`;
// realistic-looking class data: Zawadi is real, the rest are stable pseudo values
function hash(s) { let h = 7; for (const c of s) h = (h * 31 + c.charCodeAt(0)) % 9973; return h; }
function score(stu, uid) { const l = learner(stu.id); if (l) { const ks = lessonIds(UNITS[uid]); const v = ks.map(k => l.progress[k]).filter(Boolean); return v.length ? Math.round(v.reduce((a, b) => a + b, 0) / v.length / 3 * 100) : null; } const h = hash(stu.id + uid); return h % 5 === 0 ? null : 45 + h % 55; }
const HEATU = ['a1', 'a2', 'a3', 'n1', 'n2', 'l1', 'co1', 's1'];

/* ---------- T00 sign-up ---------- */
R.T00 = { app: 'teacher', note: 'Teachers sign up with a school email. If the school already has a licence they join it; otherwise they start a free class of up to 30 and the school can upgrade later.',
  render() { return laptop(`<div style="display:flex;gap:50px;align-items:center;justify-content:center;flex:1">
    <div style="width:440px;display:flex;flex-direction:column;gap:16px">${buddySVG('juma', { size: 150 })}<h1 style="font-size:44px">Bring your class on the trail</h1><p style="font-size:17px;margin:0">Assign lessons from the trail, see who needs help at a glance, and run whole-class sessions on shared tablets. Free for one class.</p></div>
    <form data-submit="tSignUp" class="card" style="width:440px;padding:26px;gap:12px;border-radius:24px">
      ${field('Your name', `<input class="inp" data-f="tn" value="${esc(U.f.tn ?? 'Priya Nair')}">`)}
      ${field('School email', `<input class="inp" data-f="te" value="${esc(U.f.te ?? 'p.nair@hillside.sc.ke')}">`)}
      ${field('School', `<input class="inp" data-f="ts" value="${esc(U.f.ts ?? 'Hillside Primary, Nairobi')}">`)}
      <div class="card" style="background:var(--leaf-soft);border-color:var(--leaf);flex-direction:row;gap:10px;align-items:center">${I('school')}<span>Hillside Primary has a school licence. You’ll join it automatically.</span></div>
      <button type="submit" class="btn">Create teacher account</button><span class="mut">We’ll email a link to confirm your school address.</span></form></div>`, { nonav: true, url: 'trailbuddies.africa/teachers' }); } };
ACT.tSignUp = () => { go('T01'); toast('Welcome, Ms Priya. Your class is ready to set up.'); };

/* ---------- T01 home ---------- */
R.T01 = { app: 'teacher', note: 'A teacher’s day at a glance: a setup checklist for new classes, work that’s due, and who might need help. Every number links to the detail.',
  render() { const c = S.cls; const ck = c.checklist; const done = Object.values(ck).filter(Boolean).length; const linked = c.students.filter(s => s.linked).length;
    const items = [['students', 'Add your students', 'T02'], ['letters', 'Print picture-password cards', 'T02'], ['tablets', 'Set up class tablets', 'T06'], ['assign', 'Assign your first unit', 'T03'], ['progress', 'Check class progress', 'T04']];
    return laptop(`${head('Good morning, Ms Priya', `${esc(c.name)} · ${c.students.length} students · Thursday 22 October`, `<button type="button" class="btn" data-to="T03">${I('assign')} Assign work</button><button type="button" class="btn ghost" data-to="T06">${I('tablet')} Start classroom mode</button>`)}
      <div style="display:flex;gap:14px">${stat(c.students.length, 'Students')}${stat(linked + ' / ' + c.students.length, 'Linked to a family')}${stat(S.assignments.length, 'Assignments open')}${stat('2', 'Need a nudge', 'sun')}</div>
      <div style="display:grid;grid-template-columns:1.2fr 1fr;gap:18px;flex:1;min-height:0">
        <div class="card" style="gap:10px"><div class="row"><b style="font-size:18px">Getting started</b><span class="mut">${done} of 5 done</span></div><div class="bar"><i style="width:${done / 5 * 100}%"></i></div>
          ${items.map(([k, t, to]) => `<button type="button" class="ln" data-act="ckGo" data-k="${k}" data-to2="${to}" style="width:100%;background:none;border-left:0;border-right:0;border-top:0;color:var(--ink);text-align:left"><span style="display:flex;gap:10px;align-items:center"><span class="av" style="width:28px;height:28px;font-size:14px;background:${ck[k] ? 'var(--leaf)' : 'var(--aline)'}">${ck[k] ? I('check') : ''}</span>${t}</span><span class="mut">›</span></button>`).join('')}</div>
        <div style="display:flex;flex-direction:column;gap:18px"><div class="card" style="gap:8px"><b style="font-size:18px">Due this week</b>${S.assignments.map(a => { const d = a.to.filter(id => { const l = learner(id); return l ? l.progress['as-' + a.id] : hash(id + a.id) % 3 === 0; }).length; return `<div class="row"><span><b>${esc(a.title)}</b><br><span class="mut">${esc(a.group || 'Whole class')} · due ${esc(a.due)}</span></span><span class="pill ${d === a.to.length ? 'ok' : 'sun'}">${d} / ${a.to.length} done</span></div>`; }).join('')}</div>
          <div class="card" style="gap:8px"><b style="font-size:18px">Might need help</b><div class="row"><span>Juma K. · counting past 10</span><button type="button" class="btn sm ghost" data-to="T04">View</button></div><div class="row"><span>Amina O. · hasn’t played this week</span><button type="button" class="btn sm ghost" data-act="toast" data-msg="Gentle note sent to Amina’s family.">Nudge family</button></div></div>
          <button type="button" class="sim" data-to="S01">Switch: school admin view</button></div></div>`); } };
ACT.ckGo = (el, d) => go(d.to2);

/* ---------- T02 roster ---------- */
R.T02 = { app: 'teacher', note: 'The class roster with groups, family-link status and picture passwords. Families join with the class code; the teacher never needs a parent’s email.',
  render() { const c = S.cls;
    return laptop(`${head('Class 1B roster', 'Families link from their parent app with the class code. Children sign in on class tablets with 3 pictures.', `<button type="button" class="btn ghost" data-act="printCards">${I('users')} Print picture cards</button>`)}
      <div style="display:grid;grid-template-columns:1fr 300px;gap:18px;min-height:0;flex:1">
        <div class="card" style="padding:0;overflow:auto"><table class="tbl"><thead><tr><th>Student</th><th>Group</th><th>Family link</th><th>Pictures</th><th></th></tr></thead><tbody>${c.students.map((s, i) => `<tr><td><b>${esc(s.name)}</b></td><td><div class="seg" style="width:190px">${['Starters', 'Readers'].map(g => `<button type="button" aria-pressed="${s.group === g}" data-act="grp" data-i="${i}" data-v="${g}" style="padding:5px 8px;font-size:12px">${g}</button>`).join('')}</div></td><td>${s.linked ? '<span class="pill ok">Linked</span>' : '<span class="pill sun">Not yet</span>'}</td><td style="font-size:22px">${s.pw.map(p => PICS[p]).join(' ')}</td><td><button type="button" class="btn sm ghost" data-act="newPw" data-i="${i}">New pictures</button></td></tr>`).join('')}</tbody></table></div>
        <div style="display:flex;flex-direction:column;gap:14px"><div class="card" style="align-items:center;gap:6px;background:var(--sun-soft);border-color:var(--sun-deep)"><span class="mut">Class code for families</span><b style="font:800 34px var(--mono);letter-spacing:.08em">${esc(c.code)}</b><button type="button" class="btn sm ghost" data-act="newCode">Make a new code</button><span class="mut" style="text-align:center">Families enter it in Settings → Join a class</span></div>
          <form data-submit="addStu" class="card" style="gap:8px"><b>Add a student</b><input class="inp" data-f="sn" value="${esc(U.f.sn || '')}" placeholder="First name and initial"><button type="submit" class="btn">Add</button><span class="mut">Only a first name and initial. Pictures are chosen automatically.</span></form></div></div>`); } };
ACT.grp = (el, d) => { S.cls.students[+d.i].group = d.v; save(); render(); };
ACT.newPw = (el, d) => { const s = S.cls.students[+d.i]; s.pw = shuffle(Object.keys(PICS)).slice(0, 3); const l = learner(s.id); if (l) l.pictures = s.pw.slice(); save(); render(); toast(`New pictures for ${s.name}. Print a new card.`); };
ACT.newCode = () => { const old = S.cls.code; S.cls.code = '1B-' + Math.random().toString(36).slice(2, 6).toUpperCase(); save(); render(); toast(`Old code ${old} stops working. Linked families stay linked.`); };
ACT.addStu = () => { const n = (U.f.sn || '').trim(); if (!n) return toast('Type a name.'); S.cls.students.push({ id: uid('s'), name: n, linked: false, group: 'Starters', pw: shuffle(Object.keys(PICS)).slice(0, 3) }); S.cls.checklist.students = true; U.f.sn = ''; save(); render(); toast(n + ' added. Print their picture card.'); };
ACT.printCards = () => { S.cls.checklist.letters = true; save(); overlay(`<div class="dialog" style="max-width:860px"><div class="row"><h2 style="font-size:24px">Picture-password cards</h2><button type="button" class="btn sm" data-act="close">Close</button></div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px">${S.cls.students.map(s => `<div class="card" style="border-style:dashed;border-width:2px;align-items:center"><b>${esc(s.name)}</b><span style="font-size:38px">${s.pw.map(p => PICS[p]).join(' ')}</span><span class="mut">Class 1B · tap in this order</span></div>`).join('')}</div><span class="mut">In the real app this opens a printable A4 PDF, 9 cards per page.</span></div>`); };

/* ---------- T03 assign ---------- */
R.T03 = { app: 'teacher', note: 'Assign any unit from the trail to the whole class, a group or one child, with an optional due date. It appears on Family & Class Island on their tablets straight away.',
  render() { const sel = U.f.aU || 'a3'; const who = U.f.aWho || 'Readers'; const c = S.cls; const to = who === 'Whole class' ? c.students : c.students.filter(s => s.group === who);
    return laptop(`${head('Assign work', 'Pick a unit, choose who gets it, and set a due date if you like.')}
      <div style="display:grid;grid-template-columns:1.4fr 1fr;gap:18px;flex:1;min-height:0">
        <div class="card" style="overflow:auto;gap:12px">${SUBJECTS.map(s => `<div><b>${esc(s.name)}</b><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:6px">${s.units.map(u => `<button type="button" class="card" data-act="aU" data-u="${u.id}" style="color:var(--ink);text-align:left;${sel === u.id ? 'border:2px solid var(--leaf);background:var(--leaf-soft)' : ''}"><b>${esc(u.title)}</b><span class="mut">3 lessons + trophy</span></button>`).join('')}</div></div>`).join('')}</div>
        <div style="display:flex;flex-direction:column;gap:14px"><div class="card" style="gap:10px"><b style="font-size:18px">${esc(UNITS[sel].title)}</b><div style="display:flex;gap:6px;flex-wrap:wrap">${UNITS[sel].items.slice(0, 8).map(it => `<span class="pic" style="width:44px;height:44px">${art(it, 26)}</span>`).join('')}</div>
          ${field('Who', `<div class="seg">${['Whole class', 'Readers', 'Starters'].map(g => `<button type="button" aria-pressed="${who === g}" data-act="aWho" data-v="${g}">${g}</button>`).join('')}</div>`)}<span class="mut">${to.map(s => esc(s.name)).join(', ')}</span>
          ${field('Due', `<div class="seg">${['No date', 'Fri 23 Oct', 'Fri 30 Oct'].map(g => `<button type="button" aria-pressed="${(U.f.aDue || 'Fri 30 Oct') === g}" data-act="aDue" data-v="${g}">${g}</button>`).join('')}</div>`)}
          <button type="button" class="btn" data-act="assign">Assign to ${to.length} student${to.length === 1 ? '' : 's'}</button></div>
          <div class="card" style="gap:6px"><b>Open assignments</b>${S.assignments.map(a => `<div class="row"><span>${esc(a.title)}<br><span class="mut">${esc(a.group)} · ${esc(a.due || 'no date')}</span></span><button type="button" class="btn sm ghost" data-act="unassign" data-id="${a.id}">Remove</button></div>`).join('') || '<span class="mut">None</span>'}</div></div></div>`); } };
ACT.aU = (el, d) => { U.f.aU = d.u; render(); };
ACT.aWho = (el, d) => { U.f.aWho = d.v; render(); };
ACT.aDue = (el, d) => { U.f.aDue = d.v; render(); };
ACT.assign = () => { const u = UNITS[U.f.aU || 'a3']; const who = U.f.aWho || 'Readers'; const to = (who === 'Whole class' ? S.cls.students : S.cls.students.filter(s => s.group === who)).map(s => s.id); const due = U.f.aDue || 'Fri 30 Oct';
  const a = { id: uid('as'), unit: u.id, title: u.title, group: who, due: due === 'No date' ? '' : due, by: 'Ms Priya', to }; S.assignments.push(a); S.cls.checklist.assign = true; save(); render();
  overlay(`<div class="dialog"><h2 style="font-size:22px">Assigned “${esc(u.title)}”</h2><p style="margin:0">${to.length} students will see it on Family & Class Island${to.includes('zawadi') ? ', including Zawadi on her family tablet' : ''}.</p>${to.includes('zawadi') ? '<button type="button" class="btn" data-act="seeAssign">See it on Zawadi’s tablet</button>' : ''}<button type="button" class="btn ghost" data-act="close">Done</button></div>`); };
ACT.unassign = (el, d) => { S.assignments = S.assignments.filter(a => a.id !== d.id); save(); render(); };
ACT.seeAssign = () => { S.active = 'zawadi'; save(); U.overlay = null; go('C22'); };

/* ---------- T04 progress ---------- */
R.T04 = { app: 'teacher', note: 'A heatmap of the class across units (Zawadi’s row is live from the learner app). Children are never ranked; colour shows where to help. Click a cell for detail.',
  render() { const c = S.cls; const col = v => v == null ? 'var(--sand)' : v >= 80 ? '#bfe6cc' : v >= 60 ? '#fdf0c4' : '#f8d3c8';
    return laptop(`${head('Class progress', 'Average stars per unit, as a percentage. Grey means not started.', `<button type="button" class="btn ghost" data-act="csv">Export CSV</button>`)}
      <div class="card" style="padding:0;overflow:auto"><table class="tbl heat"><thead><tr><th>Student</th>${HEATU.map(u => `<th style="text-align:center">${esc(UNITS[u].title)}</th>`).join('')}</tr></thead><tbody>${c.students.map(s => `<tr><td><b>${esc(s.name)}</b>${s.id === 'zawadi' ? ' <span class="pill sky">live</span>' : ''}</td>${HEATU.map(u => { const v = score(s, u); return `<td class="c" style="background:${col(v)}"><button type="button" data-act="cell" data-s="${s.id}" data-u="${u}" style="border:0;background:none;font:inherit;width:100%">${v == null ? '–' : v}</button></td>`; }).join('')}</tr>`).join('')}</tbody></table></div>
      <div style="display:flex;gap:14px">${[['#bfe6cc', 'Secure (80+)'], ['#fdf0c4', 'Getting there'], ['#f8d3c8', 'Needs help'], ['var(--sand)', 'Not started']].map(([c, n]) => `<span style="display:flex;gap:6px;align-items:center" class="mut"><i style="width:16px;height:16px;border-radius:4px;background:${c};display:block"></i>${n}</span>`).join('')}</div>
      <div class="card"><b>Class-wide tricky items</b><span>Hippo (4 of 6 mixed it up with rhino) · the number 7 · “flies” vs “swims” for ducks. <button type="button" class="btn sm ghost" data-to="T03">Assign a review</button></span></div>`); } };
ACT.cell = (el, d) => { S.cls.checklist.progress = true; save(); const s = S.cls.students.find(x => x.id === d.s); const v = score(s, d.u); overlay(`<div class="dialog"><h2 style="font-size:22px">${esc(s.name)} · ${esc(UNITS[d.u].title)}</h2><p style="margin:0">${v == null ? 'Not started yet.' : `${v}% of possible stars. ${v < 60 ? 'Struggled with first tries; used hints often.' : 'Mostly right on the first try.'}`}</p><div class="list">${lessonIds(UNITS[d.u]).map((k, i) => { const l = learner(s.id); const st = l ? l.progress[k] : (v == null ? 0 : 1 + hash(s.id + k) % 3); return `<div class="ln"><span>Lesson ${i + 1}</span><span>${st ? STAR(true, 16).repeat(st) : '<span class="mut">–</span>'}</span></div>`; }).join('')}</div><button type="button" class="btn" data-act="close">Close</button></div>`); };
ACT.csv = () => toast('In the real app this downloads a CSV of the table.');

/* ---------- T05 teacher badges ---------- */
R.T05 = { app: 'teacher', note: 'Teachers make class badges and award them to one child, a group or the whole class. Linked children see the celebration on their own tablet too.',
  render() { const b = U.f.tb || (U.f.tb = { id: uid('cb'), name: '', col: '#3fa6dc', icon: 'sparkle', shape: 'shield', by: 'Ms Priya', reward: 20, how: 'Awarded by Ms Priya' }); const nm = U.f.tbn ?? '';
    return laptop(`${head('Class badges', 'Make a badge, then award it.')}
      <div style="display:grid;grid-template-columns:1fr 1.2fr;gap:18px">
        <div class="card" style="gap:12px;align-items:center">${badgeArt({ ...b, name: nm }, 160)}<b style="font-family:var(--display);font-size:24px">${esc(nm || 'Class badge')}</b>
          <input class="inp" data-f="tbn" data-live="1" value="${esc(nm)}" placeholder="e.g. Reading Rocket">
          <div style="display:flex;gap:10px">${['#3fa6dc', '#2f9e5b', '#e8664a', '#b5487a', '#e0a21b'].map(c => `<button type="button" data-act="tbSet" data-k="col" data-v="${c}" aria-label="${c}" style="width:36px;height:36px;border-radius:50%;background:${c};border:4px solid ${b.col === c ? 'var(--ink)' : 'transparent'}"></button>`).join('')}</div>
          <div style="display:flex;gap:8px">${['sparkle', 'book', 'heart', 'flag', 'globe', 'thumbup'].map(ic => `<button type="button" data-act="tbSet" data-k="icon" data-v="${ic}" aria-label="${ic}" style="width:44px;height:44px;border-radius:12px;border:2px solid ${b.icon === ic ? 'var(--leaf)' : 'var(--aline)'};background:var(--card);color:${b.col};display:grid;place-items:center">${I(ic)}</button>`).join('')}</div></div>
        <div class="card" style="gap:10px"><b style="font-size:18px">Award to</b><div class="chips">${['Whole class', 'Readers', 'Starters'].map(g => `<button type="button" class="chip" data-act="tbGroup" data-v="${g}">${g}</button>`).join('')}</div>
          <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">${S.cls.students.map(s => `<button type="button" class="chip" aria-pressed="${(U.f.tbTo || []).includes(s.id)}" data-act="tbTo" data-id="${s.id}">${esc(s.name)}</button>`).join('')}</div>
          <button type="button" class="btn sun" data-act="tbAward" ${nm.trim() && (U.f.tbTo || []).length ? '' : 'disabled'}>Award badge</button>
          ${S.classBadges.length ? `<b>Awarded so far</b><div style="display:flex;gap:8px;flex-wrap:wrap">${S.classBadges.map(x => `<span title="${esc(x.name)}">${badgeArt(x, 56)}</span>`).join('')}</div>` : ''}</div></div>`); } };
ACT.tbSet = (el, d) => { U.f.tb[d.k] = d.v; render(); };
ACT.tbTo = (el, d) => { const a = U.f.tbTo = U.f.tbTo || []; a.includes(d.id) ? a.splice(a.indexOf(d.id), 1) : a.push(d.id); render(); };
ACT.tbGroup = (el, d) => { U.f.tbTo = S.cls.students.filter(s => d.v === 'Whole class' || s.group === d.v).map(s => s.id); render(); };
ACT.tbAward = () => { const b = { ...U.f.tb, name: U.f.tbn.trim(), to: U.f.tbTo.slice() }; S.classBadges.push(b); let z = false; b.to.forEach(id => { const l = learner(id); if (l && S.links[id]) { l.badges.push(b.id); l.treasures += b.reward; (S.pendingCele[id] = S.pendingCele[id] || []).push(b.id); z = true; } }); save(); U.f.tb = null; U.f.tbn = ''; U.f.tbTo = [];
  render(); overlay(`<div class="dialog"><h2 style="font-size:22px">Awarded “${esc(b.name)}” to ${b.to.length}</h2><p style="margin:0">It shows on the classroom badge wall${z ? ', and Zawadi gets a celebration on her family tablet' : ''}.</p>${z ? '<button type="button" class="btn" data-act="seeCele" data-id="zawadi">See Zawadi’s celebration</button>' : ''}<button type="button" class="btn ghost" data-act="close">Done</button></div>`); };
// class badges must resolve in allBadges() for the learner celebration screen
const _allBadges = allBadges; allBadges = function () { return _allBadges().concat(S.classBadges.map(b => ({ ...b, custom: true }))); };

/* ---------- T06 classroom mode ---------- */
R.T06 = { app: 'teacher', note: 'Lock shared tablets to the class (children sign in with pictures), project a lesson to the board for whole-class play, and show the badge wall.',
  render() { const c = S.cls; const t = U.f.cm || 'setup';
    return laptop(`${head('Classroom mode', 'Shared tablets and the whiteboard, for whole-class sessions.', `<div class="seg" style="width:420px">${[['setup', 'Tablets'], ['board', 'Whiteboard'], ['wall', 'Badge wall']].map(([k, n]) => `<button type="button" aria-pressed="${t === k}" data-act="cm" data-k="${k}">${n}</button>`).join('')}</div>`)}
      ${t === 'setup' ? `<div style="display:grid;grid-template-columns:1fr 1fr;gap:18px"><div class="card" style="gap:10px"><b style="font-size:18px">Shared class tablets</b><p style="margin:0">Each tablet opens on the class list. A child taps their name, then their 3 pictures. Family profiles never appear on class tablets.</p><div class="ln"><span>Tablets set to ${esc(c.name)}</span>${tgl(c.deviceSet, 'devSet', 'x', 'Set tablets')}</div><span class="mut">On a real tablet: Settings → Classroom → scan this code.</span><div style="width:140px;height:140px;background:repeating-conic-gradient(var(--ink) 0 25%,#fff 0 50%) 0 0/28px 28px;border-radius:8px"></div></div>
        <div class="card" style="gap:10px"><b style="font-size:18px">Try it</b><p style="margin:0">Open a class tablet and sign in as a student. Zawadi’s pictures are dog, moon, apple.</p><button type="button" class="btn" data-act="openClsTab" ${c.deviceSet ? '' : 'disabled'}>${I('tablet')} Open a class tablet</button>${c.deviceSet ? '' : '<span class="mut">Switch on “Tablets set” first.</span>'}</div></div>`
      : t === 'board' ? `<div class="card night" style="flex:1;align-items:center;justify-content:center;gap:20px;border-radius:22px;padding:30px"><span style="color:var(--night-muted)">On the whiteboard · Whole class</span><h2 style="font-size:46px;color:#fff">Which animal lives in water?</h2><div style="display:flex;gap:24px">${UNITS.a3.items.slice(0, 3).map(it => `<button type="button" data-act="boardPick" data-id="${it.id}" data-tag="${it.tag || ''}" style="width:200px;height:200px;border-radius:28px;border:4px solid ${U.f.bp === it.id ? (it.tag === 'water' ? '#5fd38d' : '#e8664a') : '#3a3f4a'};background:var(--night-2);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;font:800 22px var(--display)">${art(it, 90)}${esc(it.label)}</button>`).join('')}</div><span style="color:var(--night-muted)">Children call out; the teacher taps the answer. Hands up, no individual scores.</span></div>`
      : `<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:14px">${c.students.map(s => { const l = learner(s.id); const n = l ? l.badges.length : 1 + hash(s.id) % 6; const cb = S.classBadges.filter(b => b.to.includes(s.id)); return `<div class="card" style="flex-direction:row;align-items:center;gap:12px"><span class="av" style="background:${AVC[pick(['coral', 'sky', 'leaf', 'berry'])]}">${esc(s.name[0])}</span><span style="flex:1"><b>${esc(s.name)}</b><br><span class="mut">${n + cb.length} badges</span></span>${cb.map(b => badgeArt(b, 40)).join('')}</div>`; }).join('')}</div><span class="mut">Badge counts celebrate effort; the wall is sorted by name, never by count.</span>`}`); } };
ACT.cm = (el, d) => { U.f.cm = d.k; render(); };
ACT.devSet = () => { S.cls.deviceSet = !S.cls.deviceSet; S.cls.checklist.tablets = S.cls.deviceSet || S.cls.checklist.tablets; save(); render(); };
ACT.openClsTab = () => { U.f.who = null; U.f.pw = []; go('C02', { cls: 1 }); };
ACT.boardPick = (el, d) => { U.f.bp = d.id; render(); say(d.tag === 'water' ? 'Yes! It lives in water!' : 'Not that one. Try again!'); };

/* ---------- S01 school admin ---------- */
const sOpts = { nav: SNAV, who: 'Mr Kamau', role: 'Head teacher · school admin', url: 'app.trailbuddies.africa/school' };
R.S01 = { app: 'staff', note: 'The school admin manages the licence, invites teachers and signs the data processing agreement. Seats are counted per active teacher.',
  render() { const sc = S.school; const used = sc.teachers.filter(t => t.status === 'Active').length;
    return laptop(`${head('Hillside Primary', 'School licence · renews 1 Jan 2027', `<button type="button" class="sim" data-to="T01">Switch: teacher view</button>`)}
      <div style="display:flex;gap:14px">${stat(used + ' / ' + sc.seats, 'Teacher seats used')}${stat(sc.teachers.reduce((n, t) => n + t.students, 0), 'Students')}${stat(sc.dpa ? 'Signed' : 'Needed', 'Data agreement', sc.dpa ? 'leaf' : 'warn')}</div>
      <div style="display:grid;grid-template-columns:1.5fr 1fr;gap:18px">
        <div class="card" style="padding:0;overflow:auto"><table class="tbl"><thead><tr><th>Teacher</th><th>Classes</th><th>Students</th><th>Status</th><th></th></tr></thead><tbody>${sc.teachers.map((t, i) => `<tr><td><b>${esc(t.name)}</b></td><td>${esc(t.classes)}</td><td class="tnum">${t.students}</td><td><span class="pill ${t.status === 'Active' ? 'ok' : 'sun'}">${esc(t.status)}</span></td><td>${t.status === 'Invite sent' ? `<button type="button" class="btn sm ghost" data-act="toast" data-msg="Invite re-sent to ${esc(t.name)}.">Resend</button>` : `<button type="button" class="btn sm ghost" data-act="tRemove" data-i="${i}">Remove</button>`}</td></tr>`).join('')}</tbody></table></div>
        <div style="display:flex;flex-direction:column;gap:14px"><form data-submit="tInvite" class="card" style="gap:8px"><b>Invite a teacher</b><input class="inp" data-f="ti" value="${esc(U.f.ti || '')}" placeholder="name@hillside.sc.ke"><button type="submit" class="btn" ${used >= sc.seats ? 'disabled' : ''}>Send invite</button>${used >= sc.seats ? '<span class="mut">All seats used. Add seats to invite more.</span>' : ''}</form>
          <div class="card" style="gap:8px"><b>Data processing agreement</b><span class="mut">Required before student data is stored. Covers the Kenya Data Protection Act 2019.</span>${sc.dpa ? '<span class="pill ok" style="align-self:flex-start">Signed by Mr Kamau</span>' : '<button type="button" class="btn sun" data-act="dpa">Review and sign</button>'}</div>
          <div class="card" style="gap:8px"><b>Seats</b><div class="row"><span>${sc.seats} seats</span><button type="button" class="btn sm ghost" data-act="seats">Add 2 seats</button></div></div></div></div>`, sOpts); } };
ACT.tInvite = () => { const e = (U.f.ti || '').trim(); if (!/^\S+@\S+\.\S+$/.test(e)) return toast('Enter a school email.'); S.school.teachers.push({ name: e, classes: '—', students: 0, status: 'Invite sent' }); U.f.ti = ''; save(); render(); toast('Invite sent.'); };
ACT.tRemove = (el, d) => { const t = S.school.teachers[+d.i]; overlay(`<div class="dialog"><h2 style="font-size:22px">Remove ${esc(t.name)}?</h2><p style="margin:0">Their classes move to you until reassigned. Student progress is kept.</p><button type="button" class="btn bad" data-act="tRemoveOk" data-i="${d.i}">Remove teacher</button><button type="button" class="btn ghost" data-act="close">Cancel</button></div>`); };
ACT.tRemoveOk = (el, d) => { S.school.teachers.splice(+d.i, 1); save(); closeOverlay(); toast('Teacher removed. Seat freed.'); };
ACT.dpa = () => { S.school.dpa = true; save(); render(); toast('Agreement signed and emailed to you.'); };
ACT.seats = () => { S.school.seats += 2; save(); render(); toast('2 seats added. Pro-rated on the next invoice.'); };
R.S02 = { app: 'staff', note: 'School-wide usage by class (anonymous totals, no child names), and a shared school library where teachers’ lessons are approved for every class.',
  render() { const rows = [['Class 1B', 'Ms Priya', 34, 412, 86], ['Reading group', 'Ms Priya', 12, 140, 91], ['Class 2A', 'Mr Otieno', 28, 260, 72]]; const lib = U.f.lib || (U.f.lib = [{ t: 'Week 3 spelling', by: 'Ms Priya', st: 'pending' }, { t: 'Nairobi National Park animals', by: 'Mr Otieno', st: 'approved' }, { t: 'Counting in Kiswahili', by: 'Ms Priya', st: 'approved' }]);
    return laptop(`${head('Reports & library', 'This term · totals only, no individual children', `<button type="button" class="btn ghost" data-act="csv">Export CSV</button>`)}
      <div class="card" style="padding:0"><table class="tbl"><thead><tr><th>Class</th><th>Teacher</th><th>Students</th><th>Lessons done</th><th>Active this week</th></tr></thead><tbody>${rows.map(r => `<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td class="tnum">${r[2]}</td><td class="tnum">${r[3]}</td><td><div style="display:flex;gap:8px;align-items:center"><div class="bar" style="width:140px"><i style="width:${r[4]}%"></i></div><span class="tnum">${r[4]}%</span></div></td></tr>`).join('')}</tbody></table></div>
      <div class="card" style="gap:8px"><b style="font-size:18px">School library</b><span class="mut">Lessons approved here appear for every teacher at Hillside.</span>${lib.map((x, i) => `<div class="row"><span><b>${esc(x.t)}</b><br><span class="mut">by ${esc(x.by)}</span></span>${x.st === 'pending' ? `<span style="display:flex;gap:8px"><button type="button" class="btn sm" data-act="libOk" data-i="${i}">Approve</button><button type="button" class="btn sm ghost" data-act="libNo" data-i="${i}">Decline</button></span>` : `<span class="pill ${x.st === 'approved' ? 'ok' : 'bad'}">${x.st}</span>`}</div>`).join('')}</div>`, sOpts); } };
ACT.libOk = (el, d) => { U.f.lib[+d.i].st = 'approved'; render(); };
ACT.libNo = (el, d) => { U.f.lib[+d.i].st = 'declined'; render(); };

/* ---------- M01 moderation ---------- */
R.M01 = { app: 'staff', note: 'Trailbuddies’ safety team reviews flagged images and reported shared lessons within 24 hours. Removing content takes it down from every family that imported it.',
  render() { const q = S.mod; const sel = q.find(m => m.id === U.f.msel) || q.find(m => m.status === 'open') || q[0]; const open = q.filter(m => m.status === 'open').length;
    return laptop(`${head('Moderation queue', `${open} open · target: reviewed within 24 hours`)}
      <div style="display:grid;grid-template-columns:1fr 1.1fr;gap:18px;flex:1;min-height:0">
        <div class="card" style="padding:6px;gap:4px;overflow:auto">${q.map(m => `<button type="button" data-act="msel" data-id="${m.id}" style="text-align:left;border:2px solid ${sel && sel.id === m.id ? 'var(--leaf)' : 'transparent'};border-radius:14px;background:${sel && sel.id === m.id ? 'var(--leaf-soft)' : 'none'};padding:10px;display:flex;gap:10px;align-items:center;color:var(--ink)"><span class="pic">${m.e}</span><span style="flex:1"><b>${esc(m.kind)}</b><br><span class="mut">${esc(m.what)} · ${m.age}h ago</span></span>${m.status === 'open' ? (m.age >= 24 ? '<span class="pill bad">Overdue</span>' : '<span class="pill sun">Open</span>') : `<span class="pill ${m.status === 'Removed' ? 'bad' : 'ok'}">${m.status}</span>`}</button>`).join('')}</div>
        ${sel ? `<div class="card" style="gap:12px"><div class="row"><b style="font-size:20px">${esc(sel.what)}</b><span class="mut" style="font-family:var(--mono)">${esc(sel.code)}</span></div><div style="height:220px;border-radius:16px;background:var(--sand);display:grid;place-items:center;font-size:110px;${sel.status === 'open' && !U.f.reveal ? 'filter:blur(14px)' : ''}">${sel.e}</div>${sel.status === 'open' && !U.f.reveal ? '<button type="button" class="btn sm ghost" data-act="reveal" style="align-self:flex-start">Show image</button>' : ''}
          <div class="ln"><span class="mut">Reason</span><span>${esc(sel.reason)}</span></div><div class="ln"><span class="mut">Imported by</span><span>${hash(sel.id) % 40 + 2} families</span></div>
          ${sel.status === 'open' ? `<div style="display:flex;gap:10px"><button type="button" class="btn" data-act="mod" data-v="Approved">Keep it</button><button type="button" class="btn bad" data-act="mod" data-v="Removed">Remove everywhere</button><button type="button" class="btn ghost" data-act="mod" data-v="Escalated">Escalate</button></div><span class="mut">The creator is told the outcome and the reason, without naming who reported.</span>` : `<span class="pill ${sel.status === 'Removed' ? 'bad' : 'ok'}" style="align-self:flex-start">${sel.status}</span>`}</div>` : '<div class="card">Queue empty.</div>'}</div>`, Object.assign({}, sOpts, { who: 'Safety team', role: 'Trailbuddies staff', url: 'admin.trailbuddies.africa/moderation', dark: true })); } };
ACT.msel = (el, d) => { U.f.msel = d.id; U.f.reveal = false; render(); };
ACT.reveal = () => { U.f.reveal = true; render(); };
ACT.mod = (el, d) => { const q = S.mod; const sel = q.find(m => m.id === U.f.msel) || q.find(m => m.status === 'open'); sel.status = d.v; U.f.reveal = false; const nxt = q.find(m => m.status === 'open'); U.f.msel = nxt ? nxt.id : sel.id; save(); render(); toast(d.v === 'Removed' ? 'Removed from every family that imported it. Creator notified.' : d.v === 'Escalated' ? 'Escalated to the senior reviewer.' : 'Kept. Reporters are told it was reviewed.'); };
